WITH cleaned AS (SELECT *, LENGTH(status) AS status_length, DATEDIFF(CURRENT_DATE(), shipped_date) AS days_since_shipped_date FROM shipments WHERE carrier IS NOT NULL) SELECT *, NTILE(10) OVER (ORDER BY cost DESC, id) AS cost_bucket, FIRST_VALUE(carrier) IGNORE NULLS OVER (PARTITION BY carrier, status ORDER BY status_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_carrier FROM cleaned;
